impl<T: crate::Float> MassMomentOfInertia<T> {
    /// The value in the largest SI-prefixed form of the base unit that doesn't
    /// exceed it, in steps of 1000 (`mg·m²`, `g·m²`, `kg·m²`).
    /// Zero, NaN and infinities stay in the base unit.
    #[inline]
    pub fn auto_unit(self) -> crate::InUnit<T, MassMomentOfInertiaUnit> {
        const SCALE: [(f64, MassMomentOfInertiaUnit); 3] = [
            (1.0, MassMomentOfInertiaUnit::KilogramSquareMeter),
            (0.001, MassMomentOfInertiaUnit::GramSquareMeter),
            (1e-6, MassMomentOfInertiaUnit::MilligramSquareMeter),
        ];
        crate::__private::auto_unit(self, &SCALE)
    }
}

